-- Run once as the dedicated Complyra application schema owner on Autonomous Database.
-- Never run the web application as ADMIN. Do not expose the database to the public internet.
CREATE TABLE complyra_kv (
  record_key VARCHAR2(240) PRIMARY KEY,
  payload CLOB NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL
);
-- Payloads are authenticated AES-256-GCM ciphertext generated by the application.
-- Preserve DATA_ENCRYPTION_KEY in a secret manager and use encrypted, tested backups.
